import binascii,json,sys,unicodedata,itertools
assert sys.version_info[:3]==(3,14,7) and unicodedata.unidata_version=='16.0.0'
specs=[['bytes',''],['bytes','20'],['bytes','215151'],['bytes','ff'],['bytes','00'*45],['bytes','00'*46],['str',''],['str','!00'],['str','é'],['str','\ud800'],['int','1'],['none'],['list']]
def value(s):
 if s[0]=='bytes': return bytes.fromhex(s[1])
 if s[0]=='str': return s[1]
 if s[0]=='int': return int(s[1])
 if s[0]=='none': return None
 if s[0]=='list': return []
rows=[]
for name in ('a2b_uu','b2a_uu'):
 f=getattr(binascii,name)
 arguments=[[],*[[s] for s in specs],*[[s,['none']] for s in specs]]
 keywords=[{},*[{key:s} for key in ('backtick','data','backtik','other') for s in specs],{'backtick':['int','1'],'other':['none']}]
 for args,kwargs in itertools.product(arguments,keywords):
  try: result={'hex':f(*map(value,args),**{k:value(v) for k,v in kwargs.items()}).hex()}
  except Exception as error: result={'error':type(error).__name__,'message':str(error)}
  rows.append({'name':name,'args':args,'kwargs':kwargs,'result':result})
print(json.dumps({'version':sys.version,'unicode':unicodedata.unidata_version,'platform':sys.platform,'byteorder':sys.byteorder,'metadata':{name:{'doc':getattr(binascii,name).__doc__,'textSignature':getattr(binascii,name).__text_signature__} for name in ('a2b_uu','b2a_uu')},'cases':rows},ensure_ascii=True))
